INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(8901, '1 Kings 21:10', '1 Kings', 21, 10, '&nbsp;دوه بدمعاشان د هغۀ مخامخ کښېنوئ چې اِلزام ورباندې ولګوى چې هغۀ د خُدائ پاک او بادشاه ګستاخى کړې ده. بيا هغه د ښار نه بهر بوځئ او سنګسار يې کړئ چې مړ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8902, '1 Kings 21:11', '1 Kings', 21, 11, '&nbsp;نو د نبوت ښار اوسېدونکو مشرانو او آفسرانو هم هغه شان وکړل لکه څنګه چې ورته ايزبل په هغه خطونو کښې ليکلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8903, '1 Kings 21:12', '1 Kings', 21, 12, '&nbsp;هغوئ اعلان وکړو چې نن روژه ونيسئ، خلق راغونډ شول او نبوت له يې د عزت ځائ ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8904, '1 Kings 21:13', '1 Kings', 21, 13, '&nbsp;هغه دوو بدمعاشانو د خلقو په مينځ کښې په هغۀ اِلزام ولګولو چې هغۀ د خُدائ پاک او د بادشاه ګستاخى کړې ده، نو هغه د ښار نه بهر بوتلے شو او سنګسار يې کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8905, '1 Kings 21:14', '1 Kings', 21, 14, '&nbsp;نو ايزبل ته دا پېغام ولېږلے شو چې، ”نبوت سنګسار شوے دے او مړ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8906, '1 Kings 21:15', '1 Kings', 21, 15, '&nbsp;څنګه چې ايزبل ته دا پېغام مِلاو شو، نو هغې اخى‌اب ته ووئيل، ”نبوت مړ دے نو لاړ شه او د انګورو هغه باغ قبضه کړه، چې کوم يې په تا باندې نۀ خرڅولو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8907, '1 Kings 21:16', '1 Kings', 21, 16, '&nbsp;نو اخى‌اب فوراً د انګورو باغ ته لاړو او قبضه يې کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8908, '1 Kings 21:17', '1 Kings', 21, 17, '&nbsp;بيا د مالِک خُدائ کلام د تِشبى پېغمبر په الياس نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8909, '1 Kings 21:18', '1 Kings', 21, 18, '&nbsp;”د سامريه بادشاه اخى‌اب له لاړ شه. هغه به تۀ د نبوت د انګورو په باغ کښې ووينې، چې په کوم باندې قبضه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8910, '1 Kings 21:19', '1 Kings', 21, 19, '&nbsp;هغۀ ته ووايه چې زۀ مالِک خُدائ هغۀ ته فرمايم چې د هغه سړى د وژلو نه پس، د هغۀ په جائيداد قبضه هم کوې څۀ؟ هغۀ ته ووايه چې زۀ داسې فرمايم، په کوم ځائ کښې چې سپو د نبوت وينه وڅټله نو سپى به هلته ستا وينه هم وڅټى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8911, '1 Kings 21:20', '1 Kings', 21, 20, '&nbsp;کله چې اخى‌اب الياس وليدو، نو هغۀ ورته ووئيل، ”زما دشمنه، زۀ دې پېدا کړم؟“ الياس ورته وفرمائيل، ”آو، تۀ مې پېدا کړې، تا خپل ځان هغه څۀ ته حواله کړے دے چې د مالِک خُدائ په نظر کښې غلط دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8912, '1 Kings 21:21', '1 Kings', 21, 21, '&nbsp;نو مالِک خُدائ تا ته فرمائى چې زۀ په تا تباهى راولم. زۀ به تا لرې کړم او ستا د خاندان هر يو نر کس به ختم کړم، کۀ هغه بوډا وى او کۀ ځوان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8913, '1 Kings 21:22', '1 Kings', 21, 22, '&nbsp;ستا خاندان به د نباط زوئ يربعام بادشاه په شان او د اخياه د زوئ بعشا بادشاه د خاندان په شان شى، ځکه چې اِسرائيليان دې د ګناه طرف ته بوتلى دى نو تا زما غصه راپارولې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8914, '1 Kings 21:23', '1 Kings', 21, 23, '&nbsp;او مالِک خُدائ د ايزبل په حقله فرمائى چې د يزرعيل په ښار کښې به سپى د هغې لاش وخورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8915, '1 Kings 21:24', '1 Kings', 21, 24, '&nbsp;ستا هر يو خپلوان چې په ښار کښې مړ شى نو سپى به يې وخورى او څوک چې په مېدان کښې مړۀ شى نو مارغان به يې وخورى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8916, '1 Kings 21:25', '1 Kings', 21, 25, '&nbsp;د اخى‌اب په شان داسې هيڅ څوک هم نۀ وُو چې د مالِک خُدائ په نظر کښې يې دومره بد عمل کړے وو او خپلې ښځې ايزبل ورباندې دا کار کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8917, '1 Kings 21:26', '1 Kings', 21, 26, '&nbsp;هغۀ ډېر د بې‌شرمۍ ګناهونه وکړل چې د بُتانو عبادت يې وکړو، لکه څنګه چې اموريانو کړى وُو، کوم چې مالِک خُدائ په هغه وخت کښې د هغه مُلک نه شړلى وُو چې بنى اِسرائيل مخ په وړاندې تلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8918, '1 Kings 21:27', '1 Kings', 21, 27, '&nbsp;کله چې اخى‌اب د الياس دا خبرې واورېدې، نو اخى‌اب خپلې جامې وشلولې او وې ويستلې او د ټاټ جامې يې واغوستلې. هغۀ خوراک نۀ کولو، د ټاټ په جامو کښې اودۀ کېدو او سر وهلے بر وهلے ګرځېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8919, '1 Kings 21:28', '1 Kings', 21, 28, '&nbsp;د مالِک خُدائ کلام په الياس پېغمبر نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8920, '1 Kings 21:29', '1 Kings', 21, 29, '&nbsp;”تا ته پته لګېدلې ده څۀ چې اخى‌اب ما ته خپل ځان څومره عاجز کړے دے؟ نو چې ترڅو پورې هغه ژوندے وى نو زۀ به په هغۀ تباهى نۀ راولم، خو د هغۀ د خپل زوئ په ژوند کښې به زۀ د اخى‌اب په خاندان باندې تباهى راولم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8921, '1 Kings 22:1', '1 Kings', 22, 1, '&nbsp;د اِسرائيل او د شام په مينځ کښې درې کاله امن وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8922, '1 Kings 22:2', '1 Kings', 22, 2, '&nbsp;خو په درېم کال د يهوداه بادشاه يهوسفط د اِسرائيل بادشاه اخى‌اب سره مِلاوېدو دپاره لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8923, '1 Kings 22:3', '1 Kings', 22, 3, '&nbsp;اخى‌اب د خپلو آفسرانو نه تپوس وکړو، ”مونږ د شام د بادشاه نه د رامات‌جِلعاد ښار واپس ولې وانۀ خستلو؟ دا خو زمونږ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8924, '1 Kings 22:4', '1 Kings', 22, 4, '&nbsp;او اخى‌اب د يهوسفط نه تپوس وکړو، ”تۀ به ما سره لاړ شې څۀ چې په رامات‌جِلعاد حمله وکړُو؟“ يهوسفط ورته ووئيل، ”لکه څنګه چې زۀ ستا ملګرے يم، نو داسې زما فوجيان ستا خپل فوجيان دى او زما آسونه ستا خپل آسونه دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8925, '1 Kings 22:5', '1 Kings', 22, 5, '&nbsp;او يهوسفط دا هم ووئيل، ”خو راځه چې اول د مالِک خُدائ سره مشوره وکړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8926, '1 Kings 22:6', '1 Kings', 22, 6, '&nbsp;نو اخى‌اب تقريباً څلور سوه پېغمبران راغونډ کړل، او تپوس يې ترې نه وکړو، ”ما له په رامات‌جِلعاد باندې حمله کول په کار دى او کۀ نه؟“ هغوئ ورته ووئيل، ”آو، حمله پرې وکړه، مالِک خُدائ به فتح درکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8927, '1 Kings 22:7', '1 Kings', 22, 7, '&nbsp;خو يهوسفط ترې نه تپوس وکړو، ”داسې يو بل پېغمبر نشته څۀ چې د هغۀ په ذريعه مونږ د مالِک خُدائ سره مشوره وکړُو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8928, '1 Kings 22:8', '1 Kings', 22, 8, '&nbsp;اخى‌اب ورته ووئيل، ”يو بل پېغمبر هم شته چې د اِمله زوئ ميکاياه دے. خو زۀ د هغۀ نه نفرت کوم، ځکه چې هغۀ زما دپاره هيڅکله هم ښۀ پېشګوئې نۀ ده کړې، همېشه بده پېشګوئې راکوى.“ يهوسفط ورته ووئيل، ”بادشاه سلامت، داسې مۀ وايه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8929, '1 Kings 22:9', '1 Kings', 22, 9, '&nbsp;نو اخى‌اب د دربار يو آفسر راوغوښتلو او ورته يې ووئيل چې لاړ شه او ميکاياه فوراً راوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8930, '1 Kings 22:10', '1 Kings', 22, 10, '&nbsp;د اِسرائيل بادشاه اخى‌اب او د يهوداه بادشاه يهوسفط خپلې شاهى چُوغې اغوستې وې او د سامريه د دروازې نه بهر په درمند کښې په خپلو تختُونو باندې ناست وُو او ټولو پېغمبرانو د هغوئ په حضور کښې پېشګويانې ورکولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8931, '1 Kings 22:11', '1 Kings', 22, 11, '&nbsp;په هغوئ کښې د کنعانه زوئ صدقياه د اوسپنې ښکر جوړ کړل او اخى‌اب ته يې ووئيل، ”مالِک خُدائ داسې فرمائى، د دې سره به تۀ د شاميانو خِلاف جنګ وکړې او تباه به يې کړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8932, '1 Kings 22:12', '1 Kings', 22, 12, '&nbsp;هغه نورو ټولو پېغمبرانو هم دغه شان وفرمائيل، ”رامات‌جِلعاد ته روان شه او تۀ به کامياب شې، مالِک خُدائ به تا له فتح درکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8933, '1 Kings 22:13', '1 Kings', 22, 13, '&nbsp;په دې دوران کښې چې کوم آفسر د ميکاياه راوستو له تلے وو نو هغۀ ميکاياه ته ووئيل، ”ګوره، نورو ټولو پېغمبرانو د بادشاه د کاميابۍ پېشګوئې ورکړې ده، نو لاړ شه او هم هغه خبرې ورته وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8934, '1 Kings 22:14', '1 Kings', 22, 14, '&nbsp;خو ميکاياه ورته وفرمائيل، ”زۀ د ژوندى مالِک خُدائ په نوم دا لوظ کوم چې هغه ما ته څۀ وائى نو زۀ به هم هغه ووايم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8935, '1 Kings 22:15', '1 Kings', 22, 15, '&nbsp;کله چې هغه د بادشاه په مخکښې حاضر شو، نو بادشاه ترې نه تپوس وکړو، ”ميکاياه، ما او يهوسفط له په رامات‌جِلعاد باندې حمله کول په کار دى او کۀ نه؟“ ميکاياه ورته د چل سره ووئيل، ”آو، حمله ورباندې وکړئ، بې‌شکه تاسو به بريالى شئ. مالِک خُدائ به تاسو له فتح درکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8936, '1 Kings 22:16', '1 Kings', 22, 16, '&nbsp;خو اخى‌اب ووئيل، ”ما درته څو ځلې وئيلى دى؟ چې کله تۀ ما ته د مالِک خُدائ په نوم خبرې کوې، نو رښتيا وايه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8937, '1 Kings 22:17', '1 Kings', 22, 17, '&nbsp;ميکاياه ورته وفرمائيل، ”ما په خوب کښې د اِسرائيل لښکر په غرونو باندې داسې خور وکتلو لکه چې د شپون نه بغېر ګډې خورې ورې وى. او مالِک خُدائ وفرمائيل چې د دې سړو مشر نشته، نو پرېږده چې هغوئ په خېر سره کورونو ته لاړ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8938, '1 Kings 22:18', '1 Kings', 22, 18, '&nbsp;اخى‌اب يهوسفط ته ووئيل، ”ما تا ته نۀ دى وئيلى څۀ چې هغه زما دپاره ښۀ پېشګوئې نۀ اوروى؟ د هغۀ پېشګوئې تل بده وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8939, '1 Kings 22:19', '1 Kings', 22, 19, '&nbsp;ميکاياه دا هم وفرمائيل چې، ”مالِک خُدائ ته غوږ ونيسه چې هغه څۀ فرمائى. ما په آسمان کښې مالِک خُدائ وليدو چې په خپل تخت باندې ناست وو او خپلې ټولې فرښتې يې ښى او ګس طرف ته ولاړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8940, '1 Kings 22:20', '1 Kings', 22, 20, '&nbsp;مالِک خُدائ تپوس وکړو چې، اخى‌اب به څوک دوکه کړى چې لاړ شى او په رامات‌جِلعاد کښې ووژلے شى؟ نو څۀ فرښتو يو څۀ وفرمائيل او نورو بل څۀ وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8941, '1 Kings 22:21', '1 Kings', 22, 21, '&nbsp;نو يوه ترې نه راوړاندې شوه، مالِک خُدائ ته ورنزدې شوه او وې فرمائيل، زۀ به هغه دوکه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8942, '1 Kings 22:22', '1 Kings', 22, 22, '&nbsp;مالِک خُدائ ترې نه تپوس وکړو چې، څنګه؟ نو هغه روح ورته ووئيل چې، زۀ به لاړ شم او د اخى‌اب په ټولو پېغمبرانو به دروغ ووايم. نو مالِک خُدائ ورته وفرمائيل چې، لاړ شه او هغه دوکه کړه. تۀ به کامياب شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8943, '1 Kings 22:23', '1 Kings', 22, 23, '&nbsp;مالِک خُدائ ستا پېغمبران دې ته جوړ کړى دى چې دروغ ووائى ځکه هغۀ په خپله دا فېصله کړې ده چې په تا تباهى راشى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8944, '1 Kings 22:24', '1 Kings', 22, 24, '&nbsp;بيا صدقياه پېغمبر ميکاياه له ورنزدې شو، په مخ يې څپېړه ورکړه او تپوس يې ترې نه وکړو، ”ستا خيال دا دے څۀ چې د مالِک خُدائ روح زما نه تلے دے او تا سره يې خبرې کړې دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8945, '1 Kings 22:25', '1 Kings', 22, 25, '&nbsp;ميکاياه ورته وفرمائيل، ”تا ته به پته ولګى چې کله تۀ د پټېدو دپاره يوې شاتنۍ کوټې ته لاړ شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8946, '1 Kings 22:26', '1 Kings', 22, 26, '&nbsp;بيا اخى‌اب خپل يو آفسر له حُکم ورکړو، ”ميکاياه ګرفتار کړه او د ښار حکمران امون او يوآس شهزاده له يې بوځه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8947, '1 Kings 22:27', '1 Kings', 22, 27, '&nbsp;هغوئ ته ووايه چې دې په قېدخانه کښې واچوى او د لږې شان روټۍ او اوبو نه بغېر دې هيڅ هم نۀ ورکوى ترڅو پورې چې زۀ په خېر سره واپس نۀ يم راغلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8948, '1 Kings 22:28', '1 Kings', 22, 28, '&nbsp;ميکاياه وفرمائيل، ”کۀ تۀ په خېر سره واپس راشې، نو مالِک خُدائ به زما په ذريعه کلام نۀ وى کړے.“ او ميکاياه دا هم وفرمائيل چې، ”زۀ څۀ وايم نو دا به ياد ساتئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
