(8951, '1 Kings 22:31', '1 Kings', 22, 31, '&nbsp;د شام بادشاه د خپلو دوه دېرشو جنګى ګاډو فوجى مشرانو له حُکم ورکړے وو چې د اِسرائيل د بادشاه نه بغېر به په هيچا باندې حمله نۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8952, '1 Kings 22:32', '1 Kings', 22, 32, '&nbsp;نو چې کله هغوئ يهوسفط بادشاه وليدو، نو د هغوئ ټولو خيال دا وو چې ګنې هغه د اِسرائيلو بادشاه دے، نو هغوئ په هغۀ باندې د حملې کولو دپاره راوګرځېدل. خو چې کله هغۀ چغه کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8953, '1 Kings 22:33', '1 Kings', 22, 33, '&nbsp;نو هغوئ ته پته لګېده چې هغه د اِسرائيل بادشاه نۀ دے، نو هغوئ ترې نه راواپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8954, '1 Kings 22:34', '1 Kings', 22, 34, '&nbsp;خو يو شامى فوجى يو غشے هسې وويشتلو او په دې باندې اخى‌اب د خپلې زغرې د جوړ په مينځ کښې ولګېدو. نو اخى‌اب د خپلې جنګى ګاډۍ چلوونکى ته آواز وکړو، ”زۀ زخمى شوم، واپس شه او د جنګ نه ووځه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8955, '1 Kings 22:35', '1 Kings', 22, 35, '&nbsp;جنګ ټوله ورځ سخت وو، او اخى‌اب بادشاه په خپله جنګى ګاډۍ کښې ايسار وو، تکيه يې وهلې وه او شاميانو ته يې مخ وو. د هغۀ د زخم نه وينه بهېدله او وينې د جنګى ګاډۍ تخت پټ کړو او په ماښام کښې هغه مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
