(8985, '2 Kings 1:12', '2 Kings', 1, 12, '&nbsp;الياس ورته وفرمائيل، ”کۀ زۀ د خُدائ پاک خِدمتګار يم، نو د آسمان نه دې اور راکوز شى او تا او ستا سړى دې ووژنى.“ نو سمدستى اور راکوز شو او آفسر او د هغۀ سړى يې ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8986, '2 Kings 1:13', '2 Kings', 1, 13, '&nbsp;بادشاه يو ځل بيا د پنځوسو سړو سره يو آفسر ورولېږلو. هغه غرۀ ته وختلو، هغه د الياس په مخکښې ټيټ شو او سوال زارى يې ورته وکړه چې، ”د خُدائ پاک خِدمتګاره، په ما او زما په سړو باندې رحم وکړه. زمونږ ژوند بچ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8987, '2 Kings 1:14', '2 Kings', 1, 14, '&nbsp;هغه نور دوه آفسران او د هغوئ سړى په آسمانى اور باندې وژلے شوى دى، خو په ما باندې رحم وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8988, '2 Kings 1:15', '2 Kings', 1, 15, '&nbsp;د مالِک خُدائ فرښتې الياس ته وفرمائيل، ”هغۀ سره لاړ شه او يرېږه مه.“ نو الياس د هغه آفسر سره بادشاه له لاړو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8989, '2 Kings 1:16', '2 Kings', 1, 16, '&nbsp;او بادشاه ته يې وفرمائيل، ”مالِک خُدائ داسې فرمائى چې تا ولې د عقرون خُدائ بعل‌زبوب نه تپوس دپاره پېغام وړُونکى لېږلى وُو؟ ستا څۀ خيال وو چې په اِسرائيل کښې خُدائ نشته؟ نو په دې وجه تۀ به روغ نۀ شې، او خامخا به مړ شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8990, '2 Kings 1:17', '2 Kings', 1, 17, '&nbsp;لکه څنګه چې مالِک خُدائ د الياس په ذريعه فرمائيلى وُو، اخزياه مړ شو. د اخزياه زامن نۀ وُو، نو د يهوداه بادشاه د يهوسفط زوئ يهورام د بادشاهۍ په دوېم کال د اخزياه ورور يورام د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8991, '2 Kings 1:18', '2 Kings', 1, 18, '&nbsp;اخزياه بادشاه چې نور هر څۀ هم کړى وُو هغه د اِسرائيل د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8992, '2 Kings 2:1', '2 Kings', 2, 1, '&nbsp;هغه وخت راغلو چې مالِک خُدائ الياس په يو زورَور باد کښې بره آسمان ته وخېژوى. الياس او اليشع د جِلجال نه روان شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8993, '2 Kings 2:2', '2 Kings', 2, 2, '&nbsp;او په لار کښې الياس اليشع ته وفرمائيل، ”اوس دلته پاتې شه، مالِک خُدائ ما له حُکم راکړے دے چې بيت‌ايل ته لاړ شم.“ خو اليشع ورته وفرمائيل، ”زۀ د ژوندى مالِک خُدائ او تا سره په خپله وفادارۍ قسم کوم چې زۀ به تا نه لاړ نۀ شم.“ نو هغوئ بيت‌ايل ته روان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8994, '2 Kings 2:3', '2 Kings', 2, 3, '&nbsp;د پېغمبرانو يوه ډله د بيت‌ايل نه راووتله، اليشع له لاړه او د هغۀ نه يې تپوس وکړو، ”تا ته پته ده څۀ چې مالِک خُدائ نن ستا نه نېک بوځى؟“ اليشع ورته وفرمائيل، ”آو، ما ته پته ده، خو دا خبره مۀ کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8995, '2 Kings 2:4', '2 Kings', 2, 4, '&nbsp;بيا الياس اليشع ته وفرمائيل، ”اوس تۀ دلته پاتې شه، مالِک خُدائ ما له حُکم راکړے دے چې يريحو ته لاړ شم.“ خو اليشع ورته وفرمائيل، ”زۀ د ژوندى مالِک خُدائ سره او تا سره په خپله وفادارۍ قسم کوم چې زۀ به ستا نه لاړ نۀ شم.“ نو هغوئ يريحو ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8996, '2 Kings 2:5', '2 Kings', 2, 5, '&nbsp;د پېغمبرانو يوه ډله چې هلته اوسېده اليشع له لاړه او د هغۀ نه يې تپوس وکړو، ”تا ته پته ده څۀ چې مالِک خُدائ نن ستا نه ستا نېک بوځى؟“ اليشع ورته وفرمائيل، ”آو، ما ته پته ده، خو ښۀ به دا وى چې تاسو ونۀ وايئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8997, '2 Kings 2:6', '2 Kings', 2, 6, '&nbsp;نو الياس اليشع ته وفرمائيل، ”دلته پاتې شه، مالِک خُدائ ما له حُکم راکړے دے چې د اُردن سيند ته لاړ شم.“ خو اليشع ورته وفرمائيل، ”زۀ د ژوندى مالِک خُدائ او ستا په سر قسم خورم چې زۀ به تا نه لاړ نۀ شم.“ نو هغوئ دواړه روان شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8998, '2 Kings 2:7', '2 Kings', 2, 7, '&nbsp;او پنځوس پېغمبران ورپسې لاړل. الياس او اليشع د اُردن سيند سره ودرېدل او هغه پنځوس پېغمبران ترې نه لږ لرې ودرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8999, '2 Kings 2:8', '2 Kings', 2, 8, '&nbsp;بيا الياس خپله چُوغه وويستله، راغونډه يې کړه او سيند يې ورباندې ووهلو، اوبۀ په دوه حِصو کښې تقسيم شوې او هغه او اليشع په اوچه زمکه باندې د سيند نه پورې وتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9000, '2 Kings 2:9', '2 Kings', 2, 9, '&nbsp;هلته، الياس اليشع ته وفرمائيل، ”د هغې نه مخکښې چې زۀ ستا نه بوتلے شم ما ته ووايه چې زۀ ستا دپاره څۀ وکړم.“ اليشع ورته وفرمائيل، ”ما له دې ستا د روح يو په دوه برخه راکړے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');